def feats(s):
    from collections import Counter
    ys=[p[0] for p in s]; xs=[p[1] for p in s]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    rc=Counter(p[0] for p in s)
    bar_row=[r for r,n in rc.items() if n==3][0]
    tip=[p for p in s if rc[p[0]]==1][0]
    up = bar_row > tip[0]  # bar below tip => points up
    return dict(y0=y0,y1=y1,x0=x0,x1=x1,bar_row=bar_row,tipy=tip[0],tipx=tip[1],up=up)

